}, [browserController]);

edits.newText:
bool isTrackVisible(String path) {
  if (!isMounted()) return false;
  if (!scroll.hasClients) return false;
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;

  final rowBox = rowContext.findRenderObject();
  if (rowBox is! RenderBox || !rowBox.hasSize) return false;

  // The Scrollable's RenderBox works as the viewport rect reference.
  final viewportBox =
      scroll.position.context.storageContext.findRenderObject();
  if (viewportBox is! RenderBox || !viewportBox.hasSize) return false;

  const tolerance = 1.0;

  final rowTopLeft = rowBox.localToGlobal(Offset.zero);
  final viewportTopLeft = viewportBox.localToGlobal(Offset.zero);
  final rowRect = Rect.fromLTWH(
    rowTopLeft.dx,
    rowTopLeft.dy,
    rowBox.size.width,
    rowBox.size.height,
  );
  final viewportRect = Rect.fromLTWH(
    viewportTopLeft.dx,
    viewportTopLeft.dy,
    viewportBox.size.width,
    viewportBox.size.height,
  );

  return rowRect.bottom > viewportRect.top + tolerance &&
      rowRect.top < viewportRect.bottom - tolerance;
}

// Register the scroll-to-track + visibility implementations onto the passed
// handle; clear them on dispose / handle swap so a stale browser never
// answers a call.
useEffect(() {
  browserController?._scrollToTrack = scrollToTrack;
  browserController?._isTrackVisible = isTrackVisible;
  return () {
    browserController?._scrollToTrack = null;
    browserController?._isTrackVisible = null;
  };
}, [browserController]);

